def new_session(browser, headless=False, extra=None):
    b = browser.lower()
    names = {'chrome': 'chrome', 'firefox': 'firefox', 'edge': 'MicrosoftEdge'}
    if b not in names:
        raise ValueError(f'unsupported browser: {browser}')
    caps = {'browserName': names[b]}
    if headless and b == 'chrome':
        caps['goog:chromeOptions'] = {'args': ['--headless=new']}
    if headless and b == 'firefox':
        caps['moz:firefoxOptions'] = {'args': ['-headless']}
    caps.update(extra or {})
    return {'capabilities': {'alwaysMatch': caps}}

