function toRequest(sessionId, command, args = {}) {
  const s = `/session/${sessionId}`;
  switch (command) {
    case 'get':
      return { method: 'POST', path: `${s}/url`, body: { url: args.url } };
    case 'findElement': {
      const map = { id: ['css selector', '#' + args.value], css: ['css selector', args.value], xpath: ['xpath', args.value] };
      const m = map[args.by];
      if (!m) throw new Error('unknown strategy ' + args.by);
      return { method: 'POST', path: `${s}/element`, body: { using: m[0], value: m[1] } };
    }
    case 'click':
      return { method: 'POST', path: `${s}/element/${args.elementId}/click`, body: {} };
    case 'getTitle':
      return { method: 'GET', path: `${s}/title`, body: null };
    case 'quit':
      return { method: 'DELETE', path: s, body: null };
    default:
      throw new Error('unknown command ' + command);
  }
}
